/// <summary>
/// CB175-SalesConfirmation
/// Extension of class <c>SalesConfirmDP</c>
/// </summary>
[ExtensionOf(classStr(SalesConfirmDP))]
internal final class METSalesConfirmDP_Extension
{
    private boolean isPickedCaseslIneProcessed;
    private SalesTotals metCachedSalesTotals;
    private SalesId metCachedSalesTotalsSalesId;
    private Map metCachedTaxAmountByTrans;
    private Map metCachedWetAmountByTrans;
    private CompanyInfo metCachedCompanyInfo;
    private Map metCachedSiteInventDimId;
    private RecId metLastCustConfirmTransRecId;
    private SalesQty metLastSalesQty;
}

Method.Source:
    /// <summary>
    /// CB175-SalesConfirmation
    /// Initializes a sales order confirmation header.
    /// </summary>
    /// <returns>
    /// The initialized <c>SalesConfirmHeaderTmp</c> sales order confirmation header record.
    /// </returns>
    protected SalesConfirmHeaderTmp initializeSalesOrderConfirmationHeader()
    {
        #ISOCountryRegionCodes
        #PrintMgmtSetup

        SysDocuBrandDetails docuBrandDetails;
        CompanyInfo           companyInfo           = this.getCachedCompanyInfo();
        SalesConfirmHeaderTmp salesConfirmHeaderTmp = next initializeSalesOrderConfirmationHeader();
        SalesTable            salesTable            = SalesTable::find(salesConfirmHeaderTmp.SalesId);
        METIndustryKeyTable   industryKey           = METIndustryKeyTable::find(METCustTable::find(salesTable.CustAccount).IndustryKey);

        SalesConfirmContract salesConfirmContract = this.parmSalesConfirmContract();
        SRSCatalogItemName name = salesConfirmContract.parmMetcashReportName();

        if (name)                   //Bug 190339: CB173 - Sales order report error fix
        {
            container reportDesignNameContainer = SrsReportRunUtil::getReportAndDesignName(name);

            select firstonly docuBrandDetails
            where docuBrandDetails.ReportName ==  conPeek(reportDesignNameContainer, 1)
                && docuBrandDetails.METIndustryKey == industryKey.IndustryKey;

            if (docuBrandDetails)
            {
                salesConfirmHeaderTmp.CompanyLogo     = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
                salesConfirmHeaderTmp.CompanyName     = industryKey.IndustryChannel;
                salesConfirmHeaderTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
                salesConfirmHeaderTmp.CompanyPhone    = docuBrandDetails.Phone;
                salesConfirmHeaderTmp.METSiteAddress  = docuBrandDetails.displayAddress();
                salesConfirmHeaderTmp.METSalesOrderConfirmFormNotes = docuBrandDetails.METReportNotes;
            }
        }

        salesConfirmHeaderTmp.CompanyEmail           = companyInfo.email();
        salesConfirmHeaderTmp.METCustAccount         = salesTable.CustAccount;
        salesConfirmHeaderTmp.METContactPersonId     = salesTable.contactPersonName();
        salesConfirmHeaderTmp.METOrderDiscount       = salesConfirmHeaderTmp.TotalTaxBaseAmount * salesTable.DiscPercent /100;
        salesConfirmHeaderTmp.METSalesOrderType      = salesTable.METSalesOrderType;
        salesConfirmHeaderTmp.METCustName            = salesTable.customerName();
        salesConfirmHeaderTmp.METSalesOrderDate      = DateTimeUtil::date(salesTable.CreatedDateTime);
        salesConfirmHeaderTmp.METSOCreateTime        = time2Str(DateTimeUtil::time(this.parmCustConfirmJour().CreatedDateTime), TimeSeparator::Colon, TimeFormat::AMPM);
        salesConfirmHeaderTmp.METSOConfirmCreateTime = time2Str(DateTimeUtil::time(this.parmCustConfirmJour().CreatedDateTime), TimeSeparator::Colon, TimeFormat::AMPM);
        salesConfirmHeaderTmp.METEntityId            = strUpr(curExt());
        salesConfirmHeaderTmp.ConfirmDate            = DateTimeUtil::date(this.parmCustConfirmJour().CreatedDateTime);

        return salesConfirmHeaderTmp;
    }

    /// <summary>
    /// CB175-SalesConfirmation
    /// Initializes a sales order confirmation line.
    /// </summary>
    /// <param name = "_salesConfirmHeaderTmp">
    /// A <c>SalesConfirmHeaderTmp</c> record which is the sales order confirmation header.
    /// </param>
    /// <param name = "_confirmationLineSelection">
    /// A <c>SalesConfirmDPConfirmationLineQuerySelection</c> object which the sales order confirmation line should be initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>SalesConfirmDetailsTmp</c> sales order confirmation line record.
    /// </returns>
    protected SalesConfirmDetailsTmp initializeSalesOrderConfirmationLine(
        SalesConfirmHeaderTmp                           _salesConfirmHeaderTmp,
        SalesConfirmDPConfirmationLineQuerySelection    _confirmationLineSelection)
    {
        SalesConfirmDetailsTmp  salesConfirmTmp;
        SalesQty                reserveQty;

        CustConfirmTrans        custConfirmTrans = _confirmationLineSelection.parmCustConfirmTrans();
        SalesLine               SalesLine        = custConfirmTrans.salesLine();
        METSalesLine            METSalesLine     = METSalesLine::find(SalesLine.RecId);
        METCase                 pickedCases       = custConfirmTrans.METPickedCases;
        METCase                 pickedBrokenCases = custConfirmTrans.METPickedBrokenCases;
        Qty                     qtyInSalesUOM;

        metLastCustConfirmTransRecId = custConfirmTrans.RecId;
        metLastSalesQty               = SalesLine.SalesQty;

        salesConfirmTmp = next initializeSalesOrderConfirmationLine(_salesConfirmHeaderTmp, _confirmationLineSelection);

        if (METSalesLine.SubstitutionType == METSalesItemSubstitutionType::AlternateSuggestion)
        {
            salesConfirmTmp.METSubstituteOriginalItemID     = SalesLine.ItemId;
            salesConfirmTmp.METSubstituteOriginalItemName   = InventTable::find(SalesLine.ItemId).productName(SystemParameters::getSystemLanguageId());
            salesConfirmTmp.METItemStatus                   = custConfirmTrans.METReasonId;
            salesConfirmTmp.METSubstituteAlternateItemID    = METSalesLine.SubstituteItemID;
            salesConfirmTmp.METSubstituteAlternateItemName  = InventTable::find(METSalesLine.SubstituteItemID).productName(SystemParameters::getSystemLanguageId());

        }

        salesConfirmTmp.METLineNo              = real2int(custConfirmTrans.LineNum);
        salesConfirmTmp.METBarCode             = SalesLine.BarCode;
        salesConfirmTmp.METIndicators          = salesLine.getSalesLineInvoiceIndicator(true);
        salesConfirmTmp.METReasonId            = custConfirmTrans.METReasonId;
        salesConfirmTmp.METCustAvailDate       = custConfirmTrans.METCustAvailDate;
        reserveQty                             = abs(SalesLine.reservedPhysical()) + abs(SalesLine.pickedInTotalInventUnit());

        if (custConfirmTrans.METSuppliedQty == 0)
        {
            METInventItemOrderSetup metInventItemOrderSetup;
            metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(custConfirmTrans.ItemId, custConfirmTrans.inventDim().InventSiteId);

            if (metInventItemOrderSetup && metInventItemOrderSetup.UnavailReason)
            {
                salesConfirmTmp.METReasonId = metInventItemOrderSetup.UnavailReason;
            }
        }

        this.primeSalesTotalsCache(salesLine);

        METLegalEntityType metLegalEntityType = this.getCachedCompanyInfo().METLegalEntityType;

        salesConfirmTmp.TaxAmount    = this.getCachedTaxAmount(salesLine.InventTransId);
        salesConfirmTmp.METWetAmount = this.getCachedWetAmount(salesLine.InventTransId);

        salesConfirmTmp.SalesPrice  = this.getSalesLineBaseCost(salesLine.InventTransId);

        if (this.getCachedCompanyInfo().METLegalEntityType == metLegalEntityType::Liquor
              && pickedCases != 0
              || pickedBrokenCases != 0)
        {
            if (pickedCases != 0
                && !isPickedCaseslIneProcessed)
            {
                salesConfirmTmp.METSupplyQty = pickedCases;
                salesConfirmTmp.METTotalPriceExclGST = salesConfirmTmp.SalesPrice  * salesConfirmTmp.METSupplyQty;
                salesConfirmTmp.TaxAmount = salesConfirmTmp.TaxAmount * salesConfirmTmp.METSupplyQty;
                salesConfirmTmp.METWetAmount = salesConfirmTmp.METWetAmount * salesConfirmTmp.METSupplyQty;

                if (!SalesLine.PdsCWQty)
                {
                    salesConfirmTmp.METTotalCartonsSupplied    = pickedCases;
                    salesConfirmTmp.METTotalCartonsAdded       = salesConfirmTmp.Qty;
                }
            }

            if (pickedBrokenCases != 0
                  && isPickedCaseslIneProcessed)
            {
                salesConfirmTmp.SalesUnitTxt = METConstants::unitEach;
                salesConfirmTmp.METSupplyQty = pickedBrokenCases;
                salesConfirmTmp.Qty          = pickedBrokenCases;

                if(SalesLine.SalesUnit != METConstants::unitEach)
                {
                    qtyInSalesUOM = UnitOfMeasureConverter::convert(salesConfirmTmp.METSupplyQty,
                                                                    UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach),
                                                                    UnitOfMeasure::unitOfMeasureIdBySymbol(SalesLine.SalesUnit),
                                                                    NoYes::No,
                                                                    EcoResProduct::findByProductNumber(SalesLine.itemid).RecId,
                                                                    NoYes::No);
                }
                else
                {
                    qtyInSalesUOM = salesConfirmTmp.METSupplyQty;
                }

                salesConfirmTmp.METTotalPriceExclGST = salesConfirmTmp.SalesPrice * qtyInSalesUOM;
                salesConfirmTmp.TaxAmount = salesConfirmTmp.TaxAmount * qtyInSalesUOM;
                salesConfirmTmp.METWetAmount = SalesConfirmTmp.METWetAmount * qtyInSalesUOM;

                if (!SalesLine.PdsCWQty)
                {
                    salesConfirmTmp.METTotalCartonsSupplied = qtyInSalesUOM;
                }
            }

            salesConfirmTmp.METTotalPriceIncGST  = salesConfirmTmp.METTotalPriceExclGST + salesConfirmTmp.METWetAmount + salesConfirmTmp.TaxAmount;
        }
        else
        {
            // populate default so confirmation line values.
            salesConfirmTmp.METSupplyQty = custConfirmTrans.METSuppliedQty;

            if (metLegalEntityType == metLegalEntityType::Food)
            {
                salesConfirmTmp.METTotalPriceExclGST = salesLine.SalesPrice;
                salesConfirmTmp.METTotalPriceIncGST = salesConfirmTmp.TaxAmount + salesConfirmTmp.METTotalPriceExclGST;
            }
            else if (metLegalEntityType == metLegalEntityType::Liquor)
            {
                salesConfirmTmp.METTotalPriceExclGST = salesLine.SalesPrice;
                salesConfirmTmp.METWetAmount         = salesConfirmTmp.METWetAmount;
                salesConfirmTmp.METTotalPriceIncGST  = salesConfirmTmp.METTotalPriceExclGST + salesConfirmTmp.METWetAmount + salesConfirmTmp.TaxAmount;
            }

            if (!SalesLine.PdsCWQty)
            {
                // Bug 225226: CB175 - SO Confirmation - Qty Supplied not aligned on Service Level Summary table and Line Detail
                //salesConfirmTmp.METTotalCartonsSupplied    = abs(SalesLine.pickedInTotalSalesUnit()) + abs(SalesLine.reservedPhysicalInSalesUnit());
                salesConfirmTmp.METTotalCartonsSupplied    = custConfirmTrans.METSuppliedQty;
                salesConfirmTmp.METTotalCartonsAdded       = salesConfirmTmp.Qty;
            }
        }

        if (!SalesLine.PdsCWQty)
        {
            UnitOfMeasureSymbol defaultSellUnit     = this.getDefaultSellUnit(salesLine);
            salesConfirmTmp.METTotalCartonsSupplied = this.getTotalCartonBasedSellUnitAndQty(salesLine, salesLine.SalesUnit, custConfirmTrans.METSuppliedQty, defaultSellUnit);
            salesConfirmTmp.METTotalCartonsAdded    = this.getTotalCartonBasedSellUnitAndQty(salesLine, salesLine.SalesUnit, salesLine.SalesQty, defaultSellUnit);
        }

        // Bug 248887: CB175 - Ordered Qty Mapped Incorrectly, Supplied Qty Not Populated at Time Report is Generated
        // custConfirmTrans.Qty is init from SalesParmLine.DeliverNow which is not the ordered qty
        salesConfirmTmp.METRebate               = this.getSalesLinePriceComponent(salesLine.InventTransId, true);
        salesConfirmTmp.METRebateFees           = MarkupTrans::findValue(tableNum(CustConfirmTrans), custConfirmTrans.RecId).CalculatedAmount;
        salesConfirmTmp.METSalesLineQtyOrdered  = custConfirmTrans.METSalesLineQtyOrdered;

        if (SalesLine.PdsCWQty)
        {
            salesConfirmTmp.METTotalCartonsSupplied    = abs(SalesLine.pdsCWPickedInTotal()) + abs(SalesLine.pdsCWReservedPhysical());
            salesConfirmTmp.METTotalCartonsAdded       = abs(SalesLine.PdsCWQty);
        }

        if (strFind(metsalesLine.Indicators, METConstants::PromotionInd, 1, strLen(metsalesLine.Indicators)))
        {
            salesConfirmTmp.METIsPromotionInd  = NoYes::Yes;
        }

        return salesConfirmTmp;
    }

    private CompanyInfo getCachedCompanyInfo()
    {
        if (!metCachedCompanyInfo)
        {
            metCachedCompanyInfo = CompanyInfo::find();
        }

        return metCachedCompanyInfo;
    }

    private void primeSalesTotalsCache(SalesLine _salesLine)
    {
        if (metCachedSalesTotals && metCachedSalesTotalsSalesId == _salesLine.SalesId)
        {
            return;
        }

        TmpTaxWorkTrans     tmpTaxWorkTrans;
        METLegalEntityType  metLegalEntityType = this.getCachedCompanyInfo().METLegalEntityType;

        metCachedSalesTotals = SalesTotals::construct(_salesLine.salesTable());
        metCachedSalesTotals.calc();
        metCachedSalesTotalsSalesId = _salesLine.SalesId;

        tmpTaxWorkTrans.setTmpData(metCachedSalesTotals.tax().tmpTaxWorkTrans());

        metCachedTaxAmountByTrans = new Map(Types::String, Types::Real);
        metCachedWetAmountByTrans = new Map(Types::String, Types::Real);

        while select tmpTaxWorkTrans
        {
            if ((strScan(tmpTaxWorkTrans.TaxCode, METConstants::TaxCodeWEG, 1, strLen(tmpTaxWorkTrans.TaxCode))) ||
                (strScan(tmpTaxWorkTrans.TaxCode, METConstants::TaxCodeGST, 1, strLen(tmpTaxWorkTrans.TaxCode))))
            {
                this.accumulateMapAmount(metCachedTaxAmountByTrans, tmpTaxWorkTrans.InventTransId, abs(tmpTaxWorkTrans.SourceRegulateAmountCur));
            }
            else if (strScan(tmpTaxWorkTrans.TaxCode, METConstants::TaxCodeWET, 1, strLen(tmpTaxWorkTrans.TaxCode)) && metLegalEntityType == metLegalEntityType::Liquor)
            {
                this.accumulateMapAmount(metCachedWetAmountByTrans, tmpTaxWorkTrans.InventTransId, abs(tmpTaxWorkTrans.SourceRegulateAmountCur));
            }
        }
    }

    private void accumulateMapAmount(Map _map, InventTransId _key, Amount _amount)
    {
        Amount existingAmount;

        if (_map.exists(_key))
        {
            existingAmount = _map.lookup(_key);
            _map.remove(_key);
        }

        _map.insert(_key, existingAmount + _amount);
    }

    /// <summary>
    /// CB175-SalesConfirmation
    /// Get SalesLine Price Component using InventTransId
    /// </summary>
    /// <param name = "_inventTransId">sales line inventTransId</param>
    /// <param name = "_includeInRebatesOrFees">true or false</param>
    /// <returns>value</returns>
    private Amount getSalesLinePriceComponent(InventTransId _inventTransId, boolean _includeInRebatesOrFees)
    {
        METComponentCode            metComponentCode;
        METSalesLinePriceComponent  metSalesLinePriceComponent;

        if (_includeInRebatesOrFees)
        {
            select sum(value) from metSalesLinePriceComponent
                join metComponentCode
                    where metSalesLinePriceComponent.Component == metComponentCode.Component
                    && metSalesLinePriceComponent.InventTransId == _inventTransId
                    && metComponentCode.IncludeInRebatesOrFees == _includeInRebatesOrFees;
        }
        else
        {
            select sum(value) from metSalesLinePriceComponent
                join metComponentCode
                    where metSalesLinePriceComponent.Component == metComponentCode.Component
                    && metSalesLinePriceComponent.InventTransId == _inventTransId
                    && metComponentCode.IncludeInCostOrBaseCost == NoYes::Yes;
        }

        return metSalesLinePriceComponent.Value;
    }

    /// <summary>
    /// Inserts the sales order confirmation line.
    /// </summary>
    /// <param name = "_salesConfirmDetailsTmp">
    /// A <c>SalesConfirmDetailsTmp</c> sales order confirmation line record to insert.
    /// </param>
    protected void insertSalesOrderConfirmationLine(SalesConfirmDetailsTmp _salesConfirmDetailsTmp)
    {
        SalesQty salesQty;

        if (metLastCustConfirmTransRecId == _salesConfirmDetailsTmp.CustConfirmTrans)
        {
            salesQty = metLastSalesQty;
        }
        else
        {
            SalesLine           salesline;
            CustConfirmTrans    custConfirmTrans;

            select SalesQty from salesline
                exists join custConfirmTrans
                    where custConfirmTrans.RecId == _salesConfirmDetailsTmp.CustConfirmTrans &&
                          custConfirmTrans.InventTransId == salesline.InventTransId;

            salesQty = salesline.SalesQty;
        }

        if (!isPickedCaseslIneProcessed)
        {
            _salesConfirmDetailsTmp.Qty = salesQty;
        }
        _salesConfirmDetailsTmp.Name = InventTable::find(_salesConfirmDetailsTmp.ItemId).productName(SystemParameters::getSystemLanguageId());

        next insertSalesOrderConfirmationLine(_salesConfirmDetailsTmp);

    }

    /// <summary>
    /// Creates and inserts sales order confirmation lines based on picked cases and picked broken cases.
    /// For liquor legal entities, creates two lines if both picked cases and picked broken cases exist; otherwise, creates a single line.
    /// </summary>
    /// <param name = "_salesConfirmHeaderTmp"></param>
    /// <param name = "_confirmationLineSelection"></param>
    /// <returns></returns>
    protected SalesConfirmDetailsTmp createSalesOrderConfirmationLine(
        SalesConfirmHeaderTmp                           _salesConfirmHeaderTmp,
        SalesConfirmDPConfirmationLineQuerySelection    _confirmationLineSelection)
    {
        CustConfirmTrans custConfirmTrans = _confirmationLineSelection.parmCustConfirmTrans();

        if (this.getCachedCompanyInfo().METLegalEntityType == metLegalEntityType::Liquor)
        {
            if (custConfirmTrans.METPickedCases != 0
                && custConfirmTrans.METPickedBrokenCases != 0)
            {
                isPickedCaseslIneProcessed = false;
                SalesConfirmDetailsTmp salesConfirmDetailsTmpPickedCases = this.initializeSalesOrderConfirmationLine(_salesConfirmHeaderTmp, _confirmationLineSelection);
                this.insertSalesOrderConfirmationLine(salesConfirmDetailsTmpPickedCases);
                isPickedCaseslIneProcessed = true;
            }
            else if (custConfirmTrans.METPickedBrokenCases != 0)
            {
                isPickedCaseslIneProcessed = true;
            }
        }

        return next createSalesOrderConfirmationLine(_salesConfirmHeaderTmp, _confirmationLineSelection);
    }

    /// <summary>
    /// CB175-SalesConfirmation
    /// Get SalesLine Price Component included in Cost/Base Cost.
    /// Discounts are deducted from the Cost/Base Cost.
    /// </summary>
    /// <param name="_inventTransId">Sales line InventTransId</param>
    /// <returns>Cost/Base Cost value</returns>
    private Amount getSalesLineBaseCost(InventTransId _inventTransId)
    {
        METComponentCode           metComponentCode;
        METSalesLinePriceComponent metSalesLinePriceComponent;
        Amount                      baseCost;

        while select Value
        from metSalesLinePriceComponent
        join PriceComponent
        from metComponentCode
            where metSalesLinePriceComponent.Component == metComponentCode.Component
               && metSalesLinePriceComponent.InventTransId == _inventTransId
               && metComponentCode.IncludeInCostOrBaseCost == NoYes::Yes
        {
            if (metComponentCode.PriceComponent == METPriceComponent::Discounts)
            {
                baseCost -= metSalesLinePriceComponent.Value;
            }
            else
            {
                baseCost += metSalesLinePriceComponent.Value;
            }
        }

        return baseCost;
    }

    /// <summary>
    /// Get default sell unit
    /// </summary>
    /// <param name = "_salesLine">Sales Line</param>
    /// <returns>UnitOfMeasureSymbol</returns>
    private UnitOfMeasureSymbol getDefaultSellUnit(SalesLine _salesLine)
    {
        InventDim               salesLineInventDim;
        InventDim               inventDimInventItemSalesSetup;
        InventDimId             inventItemSalesSetupInventDimId;
        InventItemSalesSetup    inventItemSalesSetup;

        salesLineInventDim = _salesLine.inventDim();

        if (!metCachedSiteInventDimId)
        {
            metCachedSiteInventDimId = new Map(Types::String, Types::String);
        }

        if (metCachedSiteInventDimId.exists(salesLineInventDim.InventSiteId))
        {
            inventItemSalesSetupInventDimId = metCachedSiteInventDimId.lookup(salesLineInventDim.InventSiteId);
        }
        else
        {
            // Default Order Settings are maintained at Item + Site level
            inventDimInventItemSalesSetup.clear();
            inventDimInventItemSalesSetup.InventSiteId = salesLineInventDim.InventSiteId;

            inventItemSalesSetupInventDimId = InventDim::findOrCreate(inventDimInventItemSalesSetup).InventDimId;
            metCachedSiteInventDimId.insert(salesLineInventDim.InventSiteId, inventItemSalesSetupInventDimId);
        }

        inventItemSalesSetup = InventItemSalesSetup::find(_salesLine.ItemId, inventItemSalesSetupInventDimId);

        return inventItemSalesSetup.METSalesUnit;
    }

    /// <summary>
    /// Get total carton based on sell unit and qty
    /// </summary>
    /// <param name = "_salesLine">SalesLine buffer</param>
    /// <param name = "_fromUnit">From Unit</param>
    /// <param name = "_qty">Qty</param>
    /// <param name = "_defaultSellUnit">default sell unti</param>
    /// <returns>qty</returns>
    private Qty getTotalCartonBasedSellUnitAndQty(SalesLine _salesLine, UnitOfMeasureSymbol _fromUnit, Qty _qty, UnitOfMeasureSymbol _defaultSellUnit)
    {
        EcoResProductRecId  productRecId;

        if (!_qty)
        {
            return 0;
        }

        // No setup or already in default sell unit
        if (!_defaultSellUnit || _defaultSellUnit == _fromUnit || _fromUnit != 'EA')
        {
            return _qty;
        }

        real qty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesLine.ItemId,
                                                                                            _salesLine.InventDimId,
                                                                                            _qty,
                                                                                            _fromUnit,
                                                                                            _defaultSellUnit,
                                                                                            NoYes::No,
                                                                                            NoYes::No);

        return qty;
    }
